import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    factors = []
    all_primes = set()
    for x in a:
        y = x
        f = {}
        d = 2
        while d * d <= y:
            if y % d == 0:
                e = 0
                while y % d == 0:
                    y //= d
                    e += 1
                f[d] = e
            d += 1
        if y > 1:
            f[y] = 1
        factors.append(f)
        all_primes.update(f)

    answer = 1
    for p in all_primes:
        # dp[h] is the sum of p^(area) for partial walks with current
        # height h above the minimum reached so far.
        dp = {0: 1}
        last_edge = 0
        power_cache = {0: 1}

        def pw(exp):
            val = power_cache.get(exp)
            if val is None:
                val = pow(p, exp, MOD)
                power_cache[exp] = val
            return val

        for edge, f in enumerate(factors, 1):
            e = f.get(p, 0)
            if e == 0:
                continue

            gap = edge - last_edge - 1
            if gap:
                dp = {h: v * pw(gap * h) % MOD for h, v in dp.items()}

            nd = {}
            for h, v in dp.items():
                # Difference +e: next height is h+e.
                z = h + e
                val = v * pw(z) % MOD
                nd[z] = (nd.get(z, 0) + val) % MOD

                # Difference -e, with a possible new minimum.
                z = h - e
                if z >= 0:
                    val = v * pw(z) % MOD
                    nd[z] = (nd.get(z, 0) + val) % MOD
                else:
                    drop = -z
                    val = v * pw(edge * drop) % MOD
                    nd[0] = (nd.get(0, 0) + val) % MOD

            dp = nd
            last_edge = edge

        gap = n - 1 - last_edge
        if gap:
            dp = {h: v * pw(gap * h) % MOD for h, v in dp.items()}

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

