import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]
    limit = max(values)

    # Smallest prime factor for every integer up to limit.
    spf = [0] * (limit + 1)
    for p in range(2, limit + 1):
        if spf[p] == 0:
            spf[p] = p
            if p * p <= limit:
                for multiple in range(p * p, limit + 1, p):
                    if spf[multiple] == 0:
                        spf[multiple] = p

    # omega[x] is the number of prime factors of x, with multiplicity.
    omega = [0] * (limit + 1)
    for x in range(2, limit + 1):
        omega[x] = omega[x // spf[x]] + 1

    nim_sum = 0
    for x in values:
        nim_sum ^= omega[x]
    print('Anna' if nim_sum else 'Bruno')

