import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    A = data[3:]
    S = 1 << 20

    # Walsh transform of x^K.
    f = [pow(x, K, MOD) for x in range(S)]
    h = 1
    while h < S:
        for i in range(0, S, h << 1):
            for j in range(i, i + h):
                x, y = f[j], f[j + h]
                f[j] = (x + y) % MOD
                f[j + h] = (x - y) % MOD
        h <<= 1

    # Walsh transform of the frequency table of input values.
    cnt = [0] * S
    for x in A:
        cnt[x] += 1
    h = 1
    while h < S:
        for i in range(0, S, h << 1):
            for j in range(i, i + h):
                x, y = cnt[j], cnt[j + h]
                cnt[j] = x + y
                cnt[j + h] = x - y
        h <<= 1

    # For a character with c negative signs, its signed subset sum over
    # cardinalities divisible by M is the corresponding binomial sum.
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * invfact[r] % MOD * invfact[n-r] % MOD

    # Compute the needed binomial sums directly, caching by c.
    cache = {}
    ans = 0
    for s, w in enumerate(f):
        c = (N - cnt[s]) // 2
        g = cache.get(c)
        if g is None:
            total = 0
            for q in range(0, N + 1, M):
                lo = max(0, q - (N - c))
                hi = min(c, q)
                for t in range(lo, hi + 1):
                    term = choose(c, t) * choose(N - c, q - t) % MOD
                    if t & 1:
                        total -= term
                    else:
                        total += term
                total %= MOD
            g = total
            cache[c] = g
        ans = (ans + w * g) % MOD
    print(ans * pow(S, MOD - 2, MOD) % MOD)

if __name__ == '__main__':
    main()

from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # A pair (x, y), x < y, constrains subarrays ending at y or later.
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        # Active pairs are those whose larger endpoint is at most the current
        # right endpoint. Their largest x determines the earliest valid start.
        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for x, idx in by_right[right]:
                heapq.heappush(heap, (-x, idx))

            if not heap:
                base += right
                continue

            largest_x = -heap[0][0]
            base += right - largest_x

            # The second-largest x among active pairs, excluding the top pair.
            # In a min-heap of negative x values, the second item is one of the
            # root's children; the smaller negative value corresponds to larger x.
            if len(heap) > 1:
                second_x = -min(heap[1][0], heap[2][0] if len(heap) > 2 else 0)
            else:
                second_x = 0

            # Removing the unique top pair improves the count for this right
            # endpoint by largest_x - second_x.
            if largest_x > second_x:
                gains[heap[0][1]] += largest_x - second_x

        return base + max(gains)

