import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)
    budget = next(it)
    processes = [tuple(next(it) for _ in range(4)) for _ in range(n)]

    def minimum_cost(target, a, p, b, q):
        # Examine the number of T machines by residue modulo a/gcd(a,b).
        # Within one residue class the cost is linear while S machines are
        # still needed, so its minimum occurs at an endpoint of that range.
        period = a // math.gcd(a, b)
        last_with_s = (target - 1) // b
        first_without_s = (target + b - 1) // b
        best = 10**30

        for residue in range(period):
            candidates = [residue]
            if residue <= last_with_s:
                candidates.append(residue + ((last_with_s - residue) // period) * period)

            first = residue
            if first < first_without_s:
                first += ((first_without_s - first + period - 1) // period) * period
            candidates.append(first)

            for y in candidates:
                x = max(0, (target - b * y + a - 1) // a)
                cost = x * p + y * q
                if cost < best:
                    best = cost
        return best

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(target, a, p, b, q)
            if total > budget:
                return False
        return True

    low = 0
    high = budget * max(max(a, b) for a, p, b, q in processes) + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == '__main__':
    main()

