        dp = [0] * (min(n, x) + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            upper = min(i, x)
            for k in range(upper, 0, -1):
                same = dp[k] * k if k < len(dp) else 0
                new = dp[k-1] * (x-k+1) * y
                dp[k] = (same + new) % MOD
            dp[0] = 0
        return sum(dp) % MOD

