class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Number of popcount operations needed to reduce each value to 1.
        steps = [0] * (n + 1)
        for value in range(2, n + 1):
            steps[value] = 1 + steps[value.bit_count()]

        # Binomial coefficients modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        answer = 0
        for target_ones in range(1, n + 1):
            # An x with target_ones set bits takes one operation to become
            # target_ones (unless target_ones is already 1).
            if target_ones != 1 and steps[target_ones] > k - 1:
                continue

            ways = 0
            ones_so_far = 0
            for i, bit in enumerate(s):
                remaining = n - i - 1
                if bit == '1':
                    needed = target_ones - ones_so_far
                    if 0 <= needed <= remaining:
                        ways += comb[remaining][needed]
                    ones_so_far += 1
            answer = (answer + ways) % MOD

        return answer

