import sys
from collections import deque

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(m)]
    queries = [(next(it), next(it)) for _ in range(q)]
    out = []
    for left, right in queries:
        parent = list(range(n + 1))
        size = [1] * (n + 1)
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for idx in range(left - 1, right):
            s, t = people[idx]
            a, b = find(s), find(t)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
        edges = [[] for _ in range(n + 1)]
        indeg = [0] * (n + 1)
        bad = False
        for idx in range(left - 1, right):
            s, t = people[idx]
            a = find(s)
            lo, hi = sorted((s, t))
            if s < t:
                for x in range(lo + 1, hi):
                    b = find(x)
                    if a == b:
                        bad = True
                        break
                    edges[a].append(b)
                    indeg[b] += 1
            else:
                for x in range(lo + 1, hi):
                    b = find(x)
                    if a == b:
                        bad = True
                        break
                    edges[b].append(a)
                    indeg[a] += 1
            if bad:
                break
        if bad:
            out.append('No')
            continue
        # Only representatives are vertices. Duplicate edges are harmless.
        reps = [i for i in range(1, n + 1) if find(i) == i]
        dq = deque(v for v in reps if indeg[v] == 0)
        seen = 0
        while dq:
            v = dq.popleft()
            seen += 1
            for w in edges[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    dq.append(w)
        out.append('Yes' if seen == len(reps) else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

