from collections import deque

n = int(sys.stdin.readline())
g = [sys.stdin.readline().strip() for _ in range(n)]

incoming = [[[] for _ in range(26)] for _ in range(n)]
outmask = [[0] * 26 for _ in range(n)]
for i in range(n):
    for j, ch in enumerate(g[i]):
        if ch != '-':
            c = ord(ch) - 97
            incoming[j][c].append(i)
            outmask[i][c] |= 1 << j

# unknown[i] has bit j set precisely when dist[i][j] is not known yet.
unknown = [(1 << n) - 1 for _ in range(n)]
dist = [[-1] * n for _ in range(n)]
q = deque()

def assign(i, j, value):
    dist[i][j] = value
    unknown[i] &= ~(1 << j)
    q.append((i, j))

# Palindromes of length zero and one are the centers of all answers.
for i in range(n):
    assign(i, i, 0)
for i in range(n):
    for j, ch in enumerate(g[i]):
        if ch != '-' and dist[i][j] == -1:
            assign(i, j, 1)

# Grow a palindrome by matching one edge on either side.
while q:
    u, v = q.popleft()
    newdist = dist[u][v] + 2
    for c in range(26):
        right_edges = outmask[v][c]
        if not right_edges:
            continue
        for i in incoming[u][c]:
            candidates = right_edges & unknown[i]
            while candidates:
                bit = candidates & -candidates
                j = bit.bit_length() - 1
                assign(i, j, newdist)
                candidates -= bit

sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

