import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    upper = vals[::2]
    lower = vals[1::2]

    cap = min(u + d for u, d in zip(upper, lower))

    def feasible(h):
        lo = max(0, h - lower[0])
        hi = min(upper[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            lo2 = max(0, h - lower[i], lo - x)
            hi2 = min(upper[i], h, hi + x)
            if lo2 > hi2:
                return False
            lo, hi = lo2, hi2
        return True

    # Feasibility is monotone in h, so find the largest feasible target sum.
    left, right = 0, cap + 1
    while right - left > 1:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    print(sum(upper) + sum(lower) - n * left)

if __name__ == '__main__':
    main()

