def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    H,W,X=data[0:3]
    P,Q=data[3]-1,data[4]-1
    vals=data[5:]
    seen=bytearray(H*W)
    start=P*W+Q
    seen[start]=1
    strength=vals[start]
    heap=[]
    def add(r,c):
        if 0<=r<H and 0<=c<W:
            idx=r*W+c
            if not seen[idx]:
                seen[idx]=1
                heapq.heappush(heap,(vals[idx],idx))
    for r,c in ((P-1,Q),(P+1,Q),(P,Q-1),(P,Q+1)):
        add(r,c)
