from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order: NE, SE, SW, NW.
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]
        size = n * m

        # straight[d][cell]: longest valid alternating 2,0,... segment
        # starting at cell and proceeding in direction d, including cell.
        straight = [array('H', [0]) * size for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n) if dr < 0 else range(n - 1, -1, -1)
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            lengths = straight[d]
            for r in rows:
                base = r * m
                nr = r + dr
                for c in cols:
                    idx = base + c
                    v = grid[r][c]
                    lengths[idx] = 1
                    nc = c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        nv = grid[nr][nc]
                        if (v == 2 and nv == 0) or (v == 0 and nv == 2):
                            lengths[idx] = 1 + lengths[nr * m + nc]

        # bent[d][cell]: longest segment starting at cell, moving in d,
        # with at most one clockwise turn available.
        bent = [array('H', [0]) * size for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            nd = (d + 1) % 4
            trd, tcd = dirs[nd]
            rows = range(n) if dr < 0 else range(n - 1, -1, -1)
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            current = bent[d]
            straight_d = straight[d]
            straight_turn = straight[nd]
            for r in rows:
                base = r * m
                nr = r + dr
                for c in cols:
                    idx = base + c
                    v = grid[r][c]
                    current[idx] = straight_d[idx]
                    if v != 0 and v != 2:
                        continue

                    # Continue in the same direction, retaining the turn.
                    nc = c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        nv = grid[nr][nc]
                        if (v == 2 and nv == 0) or (v == 0 and nv == 2):
                            val = 1 + current[nr * m + nc]
                            if val > current[idx]:
                                current[idx] = val

                    # Turn clockwise on the next move; subsequent moves are straight.
                    tr, tc = r + trd, c + tcd
                    if 0 <= tr < n and 0 <= tc < m:
                        nv = grid[tr][tc]
                        if (v == 2 and nv == 0) or (v == 0 and nv == 2):
                            val = 1 + straight_turn[tr * m + tc]
                            if val > current[idx]:
                                current[idx] = val

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            answer = max(answer, 1 + bent[d][nr * m + nc])
        return answer

