class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        adj=[[] for _ in range(n)]
        for u,v,w in edges:
            adj[u].append((v,w)); adj[v].append((u,w))
        parent=[-1]*n
        parent[0]=0
        pw=[0]*n
        order=[0]
        for u in order:
            for v,w in adj[u]:
                if v != parent[u]:
                    parent[v]=u; pw[v]=w; order.append(v)
        f0=[0]*n
        f1=[0]*n
        for u in reversed(order):
            base=0
            gains=[]
            for v,w in adj[u]:
                if parent[v]==u:
                    base+=f0[v]
                    gains.append(w+f1[v]-f0[v])
            gains.sort(reverse=True)
            pref=0
            for i,g in enumerate(gains):
                if i>=k or g<=0: break
                pref+=g
            f0[u]=base+pref
            pref=0
            for i,g in enumerate(gains):
                if i>=k-1 or g<=0: break
                pref+=g
            f1[u]=base+pref
        return f0[0]

