import sys

MOD = 998244353

def solve_case(H, W, grid):
    rowpref = []
    rowxor = []
    for s in grid:
        p = [0] * (W + 1)
        for j, ch in enumerate(s):
            p[j + 1] = p[j] ^ (ch == 'A')
        rowpref.append(p)
        rowxor.append(p[W])
    colpref = [0] * H
    colxor = [0] * W
    for j in range(W):
        z = 0
        for i in range(H):
            colpref[i] = z
            if grid[i][j] == 'A':
                z ^= 1
        colxor[j] = z
    if any(rowxor) or any(colxor):
        return 0

    n = H + W
    parent = list(range(n))
    size = [1] * n
    xr = [0] * n  # value[node] xor value[parent[node]]

    def find(a):
        if parent[a] != a:
            p = parent[a]
            parent[a] = find(p)
            xr[a] ^= xr[p]
        return parent[a]

    def unite(a, b, v):
        ra, rb = find(a), find(b)
        xa, xb = xr[a], xr[b]
        if ra == rb:
            return (xa ^ xb) == v
        if size[ra] < size[rb]:
            ra, rb = rb, ra
            xa, xb = xb, xa
        parent[rb] = ra
        xr[rb] = xa ^ xb ^ v
        size[ra] += size[rb]
        return True

    for i in range(H):
        p = rowpref[i]
        for j, ch in enumerate(grid[i]):
            if ch == 'B':
                # row seed xor col seed = 1 xor horizontal-prefix xor vertical-prefix
                v = 1 ^ p[j] ^ colpref[i]
                if not unite(i, H + j, v):
                    return 0
    roots = sum(1 for i in range(n) if find(i) == i)
    return pow(2, roots, MOD)

def main():
    data = sys.stdin.buffer
    t = int(data.readline())
    out = []
    for _ in range(t):
        H, W = map(int, data.readline().split())
        grid = [data.readline().decode().strip() for _ in range(H)]
        out.append(str(solve_case(H, W, grid)))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

