class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first = p.find('*')
        second = p.find('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                    pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        import bisect
        a, b, c = (occurrences(x) for x in parts)
        la, lb, lc = map(len, parts)
        ans = n + 1
        for start in a:
            ib = bisect.bisect_left(b, start + la)
            if ib == len(b):
                continue
            bs = b[ib]
            ic = bisect.bisect_left(c, bs + lb)
            if ic == len(c):
                continue
            end = c[ic] + lc
            if end - start < ans:
                ans = end - start
        return -1 if ans == n + 1 else ans

