class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix-index residue, retain the smallest prefix sum seen.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix_sum = 0
        answer = None
        for i, value in enumerate(nums, 1):
            prefix_sum += value
            residue = i % k

            previous_min = min_prefix[residue]
            if previous_min is not None:
                candidate = prefix_sum - previous_min
                if answer is None or candidate > answer:
                    answer = candidate

            if previous_min is None or prefix_sum < previous_min:
                min_prefix[residue] = prefix_sum

        return answer

