class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        prefix = 0
        best = None
        for i, x in enumerate(nums, 1):
            prefix += x
            r = i % k
            old = mins[r]
            if old is not None:
                value = prefix - old
                if best is None or value > best:
                    best = value
            if old is None or prefix < old:
                mins[r] = prefix
        return best

