from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(skip: int) -> int:
            g = 0
            l = 1
            count = 0
            for i, x in enumerate(nums):
                if i == skip:
                    continue
                count += 1
                g = gcd(g, x)
                l = l // gcd(l, x) * x
            return g * l if count else 0

        best = score(-1)
        for i in range(len(nums)):
            best = max(best, score(i))
        return best

