import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = bytearray(b'\x01') * limit
        prime[0] = prime[1] = 0
        for p in range(2, 101):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = 0

        if prime[n] or prime[m]:
            return -1

        # The initial value is included in the total cost. Each transition
        # adds the value of the newly reached state.
        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            digits = str(x)
            for i, ch in enumerate(digits):
                digit = ord(ch) - 48
                for changed in (digit - 1, digit + 1):
                    if 0 <= changed <= 9:
                        neighbor = int(digits[:i] + str(changed) + digits[i + 1:])
                        if not prime[neighbor] and cost + neighbor < dist[neighbor]:
                            dist[neighbor] = cost + neighbor
                            heapq.heappush(heap, (dist[neighbor], neighbor))

        return -1

