from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Suffix array by doubling.
        sa = list(range(n))
        rank = nums[:]
        k = 1
        while k < n:
            sa.sort(key=lambda x: (rank[x], rank[x + k] if x + k < n else -1))
            new_rank = [0] * n
            prev = sa[0]
            r = 0
            for x in sa[1:]:
                if (rank[prev], rank[prev + k] if prev + k < n else -1) != (rank[x], rank[x + k] if x + k < n else -1):
                    r += 1
                new_rank[x] = r
                prev = x
            rank = new_rank
            if r == n - 1:
                break
            k *= 2

        pos = [0] * n
        for q, x in enumerate(sa):
            pos[x] = q

        # Kasai LCP array; lcp[q] is LCP(sa[q-1], sa[q]).
        lcp = [0] * n
        h = 0
        for i in range(n):
            q = pos[i]
            if q == 0:
                continue
            j = sa[q - 1]
            while i + h < n and j + h < n and nums[i + h] == nums[j + h]:
                h += 1
            lcp[q] = h
            if h:
                h -= 1

        logs = [0] * (n + 1)
        for x in range(2, n + 1):
            logs[x] = logs[x // 2] + 1
        sparse = [lcp]
        p = 1
        while (1 << p) <= n:
            half = 1 << (p - 1)
            prev = sparse[-1]
            sparse.append([min(prev[x], prev[x + half]) for x in range(n - (1 << p) + 1)])
            p += 1

        # z[i] = LCP(nums, nums[i:]); handles the first-prefix condition.
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        for i in range(1, n - 1):
            first_prefix = z[i] >= i
            ri = pos[i]
            for j in range(i + 1, n):
                d = j - i
                if first_prefix:
                    answer += 1
                elif nums[i] == nums[j]:
                    rj = pos[j]
                    if ri < rj:
                        lo, hi = ri + 1, rj
                    else:
                        lo, hi = rj + 1, ri
                    length = hi - lo + 1
                    level = logs[length]
                    span = 1 << level
                    if min(sparse[level][lo], sparse[level][hi - span + 1]) >= d:
                        answer += 1
        return answer

