from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        removable = bytearray(n)
        for i in targetIndices:
            removable[i] = 1

        neg = -10**9
        # dp[j] is the maximum number of removals after processing the
        # current source prefix while retaining pattern[:j] as a subsequence.
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            if removable[i]:
                # Descending order keeps dp[j-1] from the previous prefix.
                for j in range(m, -1, -1):
                    best = dp[j] + 1  # remove this target character
                    if j and pattern[j - 1] == ch and dp[j - 1] > best:
                        best = dp[j - 1]  # retain it as the next pattern char
                    dp[j] = best
            else:
                for j in range(m, 0, -1):
                    if pattern[j - 1] == ch and dp[j - 1] > dp[j]:
                        dp[j] = dp[j - 1]

        return dp[m]

