from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse each edge so a traversal from 0 discovers nodes that can
        # reach 0 in the original graph.
        rev = [[] for _ in range(n)]
        max_w = 0
        for u, v, w in edges:
            rev[v].append((u, w))
            if w > max_w:
                max_w = w

        def feasible(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            q = [0]
            head = 0
            while head < len(q):
                v = q[head]
                head += 1
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        q.append(u)
            return len(q) == n

        if not feasible(max_w):
            return -1

        lo, hi = 1, max_w
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

