            seen[0] = 1
            q = [0]
            head = 0
            while head < len(q):
                v = q[head]
                head += 1
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        q.append(u)
            return len(q) == n

        if not feasible(max_w):
            return -1

        lo, hi = 1, max_w
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

