class Solution:
    def calculateScore(self, s: str) -> int:
        # Each stack contains unmarked earlier indices of one letter.
        stacks = [[] for _ in range(26)]
        score = 0

        for i, ch in enumerate(s):
            letter = ord(ch) - ord('a')
            mirror = 25 - letter
            if stacks[mirror]:
                # The most recent unmarked matching index is the closest one.
                score += i - stacks[mirror].pop()
            else:
                stacks[letter].append(i)

        return score

